const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let catalog,byId=new Map(),rawById=new Map(),groupById=new Map(),loads=new Map(),nodeLoads=new Map(),viewKey='',query='',homeFilter='All',ownerContent={folders:[],banners:[],donationMessage:'',settings:{},notes:[],pyqs:[],mocks:[],liveClasses:[],notifications:[],popups:[],appUpdate:{}},exam=null,tool=null,ticker=null,bannerTimer=null,loadToken=0;
function readStore(k,def){try{return JSON.parse(localStorage.getItem(k))??def}catch{return def}}
let saved=readStore('sb_hub_saved_v2',[]),history=readStore('sb_hub_history_v2',[]);if(!Array.isArray(saved))saved=[];if(!Array.isArray(history))history=[];
function store(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{return false}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.remove('hide');clearTimeout(window.toastId);window.toastId=setTimeout(()=>$('#toast').classList.add('hide'),2500)}
function glyph(id){const shapes={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',courses:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M8 5V3m8 2V3M3 10h18m-12 4h6"/>',material:'<path d="M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4Zm16 0h-4a3 3 0 0 0-3 3m7-3v15h-3a4 4 0 0 0-4 2"/>',donate:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',quiz:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',mock:'<circle cx="12" cy="13" r="8"/><path d="M12 9v5l3 2M9 2h6"/>',notes:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6m-6 4h6m-6 4h4"/>',tools:'<rect x="2" y="5" width="20" height="14" rx="3"/><path d="M6 9h.01M10 9h.01M14 9h.01M18 9h.01M6 13h.01M10 13h.01M14 13h.01M18 13h.01M7 16h10"/>',library:'<path d="M4 3h4v18H4Zm7 0h4v18h-4Zm7 2 3-1 3 15-3 1Z"/>',current:'<rect x="3" y="4" width="18" height="17" rx="2"/><path d="M7 8h4v5H7Zm8 0h2m-2 4h2M7 17h10"/>',back:'<path d="m14 6-6 6 6 6M8 12h12"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[id]||shapes.notes}</svg>`}
const nav=[['home','▦','Home'],['courses','▰','Batches'],['material','▤','Study Material'],['quiz','◎','Quizzes'],['mock','◷','Mock tests'],['notes','▤','Notes'],['current','◈','Current affairs'],['tools','⌨','Tools'],['library','▧','Library'],['donate','♡','Donate']];
function navRender(active){const inMaterial=!['home','courses','donate'].includes(active);const item=([id,icon,label])=>`<a class="navbtn ${id===active?'active':''}" href="#${id}" ${id===active?'aria-current="page"':''}><i aria-hidden="true">${glyph(id)}</i>${label}</a>`;$('#sidenav').innerHTML=[...nav.slice(0,3),nav[9]].map(item).join('')+(inMaterial?'<div class="navdivider"></div>'+nav.slice(3,9).map(item).join(''):'');$('#mobilenav').innerHTML=[nav[0],nav[1],nav[2],nav[9]].map(([id,icon,label])=>`<a href="#${id}" class="${id===active?'active':''}" ${id===active?'aria-current="page"':''}><i aria-hidden="true">${glyph(id)}</i>${label}</a>`).join('');$('#savedcount').textContent=saved.length}
function routeName(g){return g.title==='Quiz'?'quiz':g.title==='Mock Test'?'mock':g.title==='Notes'?'notes':g.kind==='typing'||g.kind==='calc'?'tools':'current'}
function groupFor(route){return catalog.groups.find(g=>routeName(g)===route)}
function saveBtn(id,title){return `<button class="save ${saved.includes(id)?'selected':''}" data-save="${esc(id)}" aria-label="${saved.includes(id)?'Unsave':'Save'} ${esc(title)}" aria-pressed="${saved.includes(id)}">${saved.includes(id)?'▣':'▧'}</button>`}
function groupStats(id){const all=catalog.items.filter(n=>n.group===id);return {questions:all.reduce((s,n)=>s+n.questions,0),sets:all.filter(n=>n.questions).length,notes:all.filter(n=>n.note).length}}
function desc(n){if(n.questions)return `${n.questions} questions${n.kind==='mock'?` · ${n.durationMinutes} min`:''}`;if(n.note)return n.kind==='html'?'Revision resource':'Revision notes';if(n.kind==='typing')return `${n.passages||0} Hindi + English passages`;if(n.kind==='calc')return '60-second practice';const kids=(n.children||[]).map(id=>byId.get(id)).filter(Boolean);return `${kids.length} topics`}
function card(n){const group=groupById.get(n.group||n.id),r=group?routeName(group):'',color=r==='mock'?'purple':r==='notes'?'orange':r==='current'?'blue':'',label=n.questions?(n.kind==='mock'?'Mock test':'Quiz'):n.note?'Notes':(n.kind==='typing'||n.kind==='calc')?'Tool':'Collection';return `<article class="card"><div class="cover ${color}"><i aria-hidden="true">${n.questions?'◎':n.note?'▤':n.kind==='typing'?'⌨':n.kind==='calc'?'⚡':'▦'}</i><small>${esc(label)}</small></div><div class="body"><span class="tag">${esc(desc(n))}</span><h3>${esc(n.title)}</h3><div class="cardfoot"><a class="textbtn" href="#node/${encodeURIComponent(n.id)}">${n.questions?'Open test':n.note?'Read notes':'Open'} →</a>${saveBtn(n.id,n.title)}</div></div></article>`}
function crumb(n){let parts=[['Home','#home']];if(viewKey==='donate')parts.push(['Donate','#donate']);else if(!['home','courses'].includes(viewKey)&&!viewKey.startsWith('course/'))parts.push(['Study Material','#material']);else if(viewKey==='courses'||viewKey.startsWith('course/'))parts.push(['Batches','#courses']);if(n){const g=groupById.get(n.group||n.id);if(g&&g.id!==n.id)parts.push([g.title,'#'+routeName(g)]);const chain=[];let p=byId.get(n.parent);while(p){chain.unshift(p);p=byId.get(p.parent)};chain.forEach(x=>parts.push([x.title,'#node/'+encodeURIComponent(x.id)]));parts.push([n.title,null])}$('#crumb').innerHTML=parts.map(([s,u],i)=>`${i?'<span>/</span>':''}${u?`<a ${i?'class="trail"':''} href="${u}">${esc(s)}</a>`:`<span class="trail">${esc(s)}</span>`}`).join('')}
function head(title,sub,search=true){return `<div class="heading"><div><h1>${esc(title)}</h1>${sub?`<p>${esc(sub)}</p>`:''}</div>${search?`<label class="search"><input id="search" aria-label="Search study content" placeholder="Search topics, tests, notes..." value="${esc(query)}"><b aria-hidden="true">⌕</b></label>`:''}</div>`}
function renderGrid(list){return list.length?list.map(card).join(''):'<p class="empty">No results.</p>'}
function isMatch(n){return [n.title,n.subtitle,...(n.path||[])].join(' ').toLocaleLowerCase().includes(query.toLocaleLowerCase().trim())}
function home(){navRender('home');crumb();$('#app').innerHTML=head(ownerContent.settings?.homeTitle||'Home','',false)+announcement()+notices()+banner()+`<div class="homegrid"><a class="homecube" href="#courses"><span class="cubeicon">${glyph('courses')}</span><h2>${esc(ownerContent.settings?.batchesLabel||'Batches')}</h2><span class="cubearrow">↗</span></a><a class="homecube" href="#material"><span class="cubeicon">${glyph('material')}</span><h2>${esc(ownerContent.settings?.materialLabel||'Study Material')}</h2><span class="cubearrow">↗</span></a></div>`+managedHome();startBanner()}
function material(){navRender('material');crumb();$('#app').innerHTML=head('Study Material',ownerContent.settings?.materialIntro||'')+`<div class="filters">${['All','Practice','Notes','Current affairs','Tools'].map(f=>`<button class="chip ${homeFilter===f?'active':''}" data-filter="${f}" aria-pressed="${homeFilter===f}">${f}</button>`).join('')}</div><div class="grid" id="grid"></div>`+managedMaterial();updateList();bindSearch();startBanner()}
function listFor(){if(viewKey==='material'){let list=query.trim()?catalog.items.filter(n=>(n.questions||n.note)&&isMatch(n)):catalog.groups;return list.filter(n=>{const g=groupById.get(n.group||n.id),r=routeName(g);return homeFilter==='All'||homeFilter==='Practice'&&['quiz','mock'].includes(r)||homeFilter==='Notes'&&r==='notes'||homeFilter==='Current affairs'&&r==='current'||homeFilter==='Tools'&&r==='tools'})}if(viewKey==='library')return saved.map(id=>byId.get(id)||groupById.get(id)).filter(Boolean).filter(isMatch);if(viewKey==='tools')return catalog.groups.filter(g=>['typing','calc'].includes(g.kind)).filter(isMatch);const n=viewKey.startsWith('node/')?byId.get(decodeURIComponent(viewKey.slice(5)))||groupById.get(decodeURIComponent(viewKey.slice(5))):groupFor(viewKey);if(!n)return [];if(query.trim()){const inTree=x=>{let p=x;while(p){if(p.id===n.id)return true;p=byId.get(p.parent)||groupById.get(p.parent)}return false};return catalog.items.filter(x=>inTree(x)&&(x.questions||x.note)&&isMatch(x))}return(n.children||[]).map(id=>byId.get(id)).filter(Boolean)}
function updateList(){const list=listFor();const grid=$('#grid');if(grid)grid.innerHTML=renderGrid(list);const count=$('#resultcount');if(count)count.textContent=`${list.length} ${query.trim()?'results':'items'}`}
function bindSearch(){const s=$('#search');if(s)s.oninput=e=>{query=e.target.value;updateList()}}
function collection(n,active){navRender(active);crumb(n);$('#app').innerHTML=`<a class="back" href="${n.parent?'#node/'+encodeURIComponent(n.parent):'#material'}">← Back</a>`+head(n.title,'')+`<div class="sectionhead"><h2>${query?'Search results':'Browse'}</h2><span class="small muted" id="resultcount"></span></div><div class="grid" id="grid"></div>`;updateList();bindSearch();prefetch(n)}
async function loadGroup(id){if(loads.has(id))return loads.get(id);const g=groupById.get(id);const p=(async()=>{const url='https://studybull.vercel.app/api/tile?'+new URLSearchParams({id:g.id,v:g.version});let response=null;try{response=await (await caches.open('studybull-content-v1')).match(url)}catch{}if(!response){response=await fetch(url);if(response.ok){try{await(await caches.open('studybull-content-v1')).put(url,response.clone())}catch{}}}if(!response.ok)throw new Error('Content download failed. Please try again.');const bytes=await response.arrayBuffer();const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),x=>x.toString(16).padStart(2,'0')).join('');if(hash!==g.sha256){try{await(await caches.open('studybull-content-v1')).delete(url)}catch{}throw new Error('Source content has changed. This snapshot needs an update. Original portal is available below.')}const d=JSON.parse(new TextDecoder().decode(bytes));function walk(n){rawById.set(String(n.id),n);for(const c of n.children||[])walk(c)}for(const n of d[0].nodes)walk(n);return rawById.get(id)})();loads.set(id,p);try{return await p}catch(e){loads.delete(id);throw e}}
async function openNode(id){const n=byId.get(id)||groupById.get(id);if(!n){$('#app').innerHTML='<div class="empty">Content not found. <a href="#material">Study Material</a></div>';return}const g=groupById.get(n.group||n.id),active=routeName(g);if(n.children.length){collection(n,active);return}document.body.classList.add('reader-mode');$('#readerbar').innerHTML=`<a class="readerexit" href="${n.parent?'#node/'+encodeURIComponent(n.parent):'#home'}" aria-label="Back to content">${glyph('back')}<span>Back</span></a>`;navRender(active);crumb(n);const token=++loadToken;$('#app').innerHTML=head(n.title,'',false)+'<div class="readerskeleton" role="status" aria-label="Opening content"><span></span><span></span><span></span></div>';try{await loadNode(n);if(token!==loadToken)return;const raw=rawById.get(id);if(n.kind==='typing')return typingSetup(n,raw);if(n.kind==='calc')return calcSetup(n);if(n.questions)return testRules(n,raw);if(n.note)return showNote(n,raw);$('#app').innerHTML='<div class="empty">Nothing here yet.</div>'}catch(e){if(token===loadToken)$('#app').innerHTML=`<div class="error">${esc(e.message)}<br><button class="textbtn" data-reload="${esc(id)}">Retry →</button></div>`}}
function testRules(n,raw){const mock=n.kind==='mock';$('#app').innerHTML=`<a class="back" href="#node/${encodeURIComponent(n.parent)}">← ${esc(byId.get(n.parent)?.title||'Back')}</a>`+head(n.title,n.path.slice(1).join(' / '),false)+`<div class="panel"><span class="tag">${mock?'Timed mock test':'Subject practice'}</span><h2>${raw.questions.length} questions</h2><div class="metrics"><div class="metric"><b>${mock?n.durationMinutes:'—'}</b>${mock?'Minutes':'No time limit'}</div><div class="metric"><b>+${mock?n.positiveMarks:1}</b>Correct answer</div><div class="metric"><b>${mock?'-'+n.negativeMarks:'0'}</b>Wrong answer</div><div class="metric"><b>0</b>Unattempted</div></div><p class="small muted">${mock?'The test submits automatically when time runs out.':'Check each answer to view its explanation.'}</p><div class="actions"><button class="btn" id="begin">${mock?'Start mock test':'Start practice'} →</button>${saveBtn(n.id,n.title)}</div></div>`;$('#begin').onclick=()=>beginTest(n,raw)}
function beginTest(n,raw){track('test-start',n.title);exam={node:n,questions:raw.questions,answers:Array(raw.questions.length).fill(null),flags:Array(raw.questions.length).fill(false),checked:Array(raw.questions.length).fill(false),pos:0,mock:n.kind==='mock',started:Date.now(),end:n.kind==='mock'?Date.now()+n.durationMinutes*60000:null,submitted:false};document.body.classList.add('testing');drawQuestion();clearInterval(ticker);if(exam.mock)ticker=setInterval(()=>{if(exam&&!exam.submitted){const remain=Math.max(0,Math.ceil((exam.end-Date.now())/1000));const t=$('#timer');if(t){t.textContent=timeText(remain);t.classList.toggle('urgent',remain<300)}if(!remain)submitTest(true)}},1000)}
function timeText(s){return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
function drawQuestion(){if(!exam)return;const e=exam,q=e.questions[e.pos],a=e.answers[e.pos],checked=!e.mock&&e.checked[e.pos],count=e.answers.filter(a=>a!==null).length;$('#app').innerHTML=`<div class="testhead"><div><h1>${esc(e.node.title)}</h1><small class="muted">${e.mock?'Mock test':'Practice'} · ${count}/${e.questions.length} answered</small></div>${e.mock?`<span class="timer" id="timer" role="timer" aria-label="Time remaining">${timeText(Math.max(0,Math.ceil((e.end-Date.now())/1000)))}</span>`:'<span class="tag">Practice</span>'}</div><div class="progress"><span style="width:${count/e.questions.length*100}%"></span></div><div class="testlayout"><section class="questionbox" aria-label="Question"><div class="qmeta"><span>Question ${e.pos+1} of ${e.questions.length}</span><span>+${e.mock?e.node.positiveMarks:1} / −${e.mock?e.node.negativeMarks:0}</span></div><div class="question" id="questiontext"></div><div id="options" role="group" aria-label="Answer options"></div>${checked?`<div class="explanation" id="explanation" aria-live="polite"></div>`:''}<div class="qactions"><button class="btn secondary" id="prev" ${e.pos===0?'disabled':''}>← Previous</button>${!e.mock&&!checked?`<button class="btn" id="check" ${a===null?'disabled':''}>Check answer</button>`:`<button class="btn" id="next">${e.pos===e.questions.length-1?'Finish':'Next →'}</button>`}</div><div class="qactions"><button class="textbtn" id="clear" ${checked?'disabled':''}>Clear answer</button><button class="textbtn" id="flag">${e.flags[e.pos]?'✓ Marked for review':'⚑ Mark for review'}</button></div></section><aside class="palette"><details ${window.innerWidth>750?'open':''}><summary>Question palette · ${e.questions.length}</summary><div class="numbers">${e.questions.map((_,i)=>`<button class="num ${e.answers[i]!==null?'done':''} ${e.flags[i]?'flag':''} ${i===e.pos?'current':''}" data-qpos="${i}" aria-label="Question ${i+1}${e.answers[i]!==null?', answered':''}${e.flags[i]?', marked for review':''}" ${i===e.pos?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><p class="small muted">Green: answered · Purple: review</p></details><button class="btn" id="submit" style="width:100%;margin-top:15px">${e.mock?'Submit test':'Finish practice'}</button><button class="textbtn" id="exit">Exit test</button></aside></div>`;$('#questiontext').textContent=q.question;$('#options').innerHTML=q.options.map((opt,i)=>`<button class="option ${a===i?'chosen':''} ${checked&&i===q.correctIndex?'correct':''} ${checked&&a===i&&a!==q.correctIndex?'wrong':''}" data-option="${i}" aria-pressed="${a===i}" ${checked?'disabled':''}><span>${String.fromCharCode(65+i)}</span><span class="optiontext"></span></button>`).join('');document.querySelectorAll('.optiontext').forEach((x,i)=>x.textContent=q.options[i]);if(checked)$('#explanation').textContent=`${a===q.correctIndex?'Correct':'Correct answer: '+String.fromCharCode(65+q.correctIndex)+'. '+q.options[q.correctIndex]}\n\n${q.explanation||''}`;document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{e.answers[e.pos]=+b.dataset.option;drawQuestion()});$('#prev').onclick=()=>{e.pos--;drawQuestion()};if($('#next'))$('#next').onclick=()=>{if(e.pos<e.questions.length-1){e.pos++;drawQuestion();window.scrollTo(0,0)}else confirmSubmit()};if($('#check'))$('#check').onclick=()=>{e.checked[e.pos]=true;drawQuestion()};$('#clear').onclick=()=>{e.answers[e.pos]=null;drawQuestion()};$('#flag').onclick=()=>{e.flags[e.pos]=!e.flags[e.pos];drawQuestion()};$('#submit').onclick=confirmSubmit;$('#exit').onclick=()=>confirmDialog('Exit test?','Your current answers will not be saved.',()=>{clearInterval(ticker);exam=null;document.body.classList.remove('testing');renderRoute()},'Exit test');document.querySelectorAll('[data-qpos]').forEach(b=>b.onclick=()=>{e.pos=+b.dataset.qpos;drawQuestion();window.scrollTo(0,0)})}
function confirmDialog(title,text,fn,label='Continue'){const d=$('#dialog');$('#dialogbody').innerHTML=`<h2>${esc(title)}</h2><p>${esc(text)}</p><div class="actions"><button class="btn" id="confirm">${esc(label)}</button><button class="btn secondary" id="cancel">Cancel</button></div>`;d.showModal();$('#confirm').onclick=()=>{d.close();fn()};$('#cancel').onclick=()=>d.close()}
function confirmSubmit(){const e=exam;if(!e)return;const left=e.answers.filter(a=>a===null).length;confirmDialog(e.mock?'Submit test?':'Finish practice?',`${left} unattempted · ${e.flags.filter(Boolean).length} marked for review.`,()=>submitTest(false),'See result')}
function submitTest(auto){if(!exam||exam.submitted)return;clearInterval(ticker);const e=exam;e.submitted=true;document.body.classList.remove('testing');let right=0,wrong=0,blank=0;e.questions.forEach((q,i)=>{if(e.answers[i]===null)blank++;else if(e.answers[i]===q.correctIndex)right++;else wrong++});const marks=right*(e.mock?Number(e.node.positiveMarks):1)-wrong*(e.mock?Number(e.node.negativeMarks):0),seconds=Math.floor((Date.now()-e.started)/1000);const result={id:e.node.id,title:e.node.title,date:new Date().toISOString(),right,wrong,blank,marks,total:e.questions.length,seconds};history=[result,...history].slice(0,25);store('sb_hub_history_v2',history);track('test-done',right+'/'+e.questions.length+' correct · '+e.node.title);$('#app').innerHTML=head('Test result',e.node.title,false)+(auto?'<p class="notice">Time is up. Test submitted.</p>':'')+`<div class="metrics"><div class="metric"><b>${Math.round(marks*100)/100}</b>Marks / ${e.questions.length*(e.mock?e.node.positiveMarks:1)}</div><div class="metric"><b>${right}</b>Correct</div><div class="metric"><b>${wrong}</b>Wrong</div><div class="metric"><b>${blank}</b>Unattempted</div></div><p class="small muted">Time: ${timeText(seconds)} · Accuracy: ${right+wrong?Math.round(right/(right+wrong)*100):0}% of attempted</p><div class="actions"><button class="btn" id="review">Review answers</button><button class="btn secondary" id="retry">Try again</button><button class="btn secondary" id="backtest">Back to tests</button></div><div id="reviewlist" class="panel hide"></div>`;$('#review').onclick=()=>{const list=$('#reviewlist');list.classList.remove('hide');list.innerHTML=e.questions.map((q,i)=>`<section class="reviewitem"><span class="tag">Question ${i+1} · ${e.answers[i]===null?'Unattempted':e.answers[i]===q.correctIndex?'Correct':'Wrong'}</span><h3>${esc(q.question)}</h3><div>${q.options.map((a,j)=>`<div class="${j===q.correctIndex?'correcttext':e.answers[i]===j?'wrongtext':''}">${String.fromCharCode(65+j)}. ${esc(a)} ${j===q.correctIndex?'✓':''}${e.answers[i]===j?' (Your answer)':''}</div>`).join('')}</div><p class="explanation">${esc(q.explanation)}</p></section>`).join('');$('#review').disabled=true;list.scrollIntoView({behavior:'auto',block:'start'})};$('#retry').onclick=()=>beginTest(e.node,{questions:e.questions});$('#backtest').onclick=()=>{exam=null;location.hash=e.mock?'mock':'quiz'};window.scrollTo(0,0)}
function inline(s){return esc(s).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>')}
function markdown(s){const lines=String(s).split('\n');let out='',table=[];function flush(){if(!table.length)return;out+='<div class="tablewrap"><table>'+table.filter(x=>!/^\s*\|?[\s:|\-]+\|?\s*$/.test(x)).map((x,i)=>`<tr>${x.replace(/^\s*\||\|\s*$/g,'').split('|').map(v=>`<${i?'td':'th'}>${inline(v.trim())}</${i?'td':'th'}>`).join('')}</tr>`).join('')+'</table></div>';table=[]}for(const line of lines){if(/^\s*\|/.test(line)){table.push(line);continue}flush();if(/^#{1,6}\s/.test(line)){const m=line.match(/^(#{1,6})\s+(.*)/);out+=`<${m[1].length===1?'h2':'h3'}>${inline(m[2])}</${m[1].length===1?'h2':'h3'}>`}else if(/^\s*[-*]\s/.test(line))out+=`<p>• ${inline(line.replace(/^\s*[-*]\s/,''))}</p>`;else if(/^\s*-{3,}\s*$/.test(line))out+='<hr>';else out+=line.trim()?`<p>${inline(line)}</p>`:'<br>'}flush();return out}
function download(name,text,type='text/plain;charset=utf-8'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function showNote(n,raw){track('note',n.title);const isHtml=Boolean(raw.htmlContent);$('#app').innerHTML=`<div class="notes"><a class="back" href="#node/${encodeURIComponent(n.parent)}">← ${esc(byId.get(n.parent)?.title||'Back')}</a>`+head(n.title,n.path.slice(1).join(' / '),false)+`<div class="actions" style="margin:0 0 20px">${saveBtn(n.id,n.title)}<button class="btn secondary" id="downloadnote">Download ${isHtml?'HTML':'text'} ↓</button></div><article class="panel notebody" id="notebody"></article></div>`;if(isHtml){const frame=document.createElement('iframe');frame.className='htmlnote';frame.title=n.title;frame.setAttribute('sandbox','');frame.srcdoc='<!doctype html><html lang="hi"><head><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'; img-src data:; font-src data:"><style>body{font:16px/1.9 system-ui,sans-serif;color:#243e33;padding:10px;overflow-wrap:anywhere}table{max-width:100%;border-collapse:collapse}td,th{padding:8px;border:1px solid #dfe6d9}img{max-width:100%}</style></head><body>'+raw.htmlContent+'</body></html>';$('#notebody').append(frame)}else $('#notebody').innerHTML=markdown(raw.notesContent||'');$('#downloadnote').onclick=()=>download('studybull-'+n.id+(isHtml?'.html':'.txt'),isHtml?raw.htmlContent:raw.notesContent,isHtml?'text/html;charset=utf-8':undefined)}
function library(){navRender('library');crumb();$('#app').innerHTML=head('My library','Saved on this browser · No cloud sync')+`<div class="sectionhead"><h2>Saved content</h2><span class="small muted" id="resultcount"></span></div><div class="grid" id="grid"></div>`+(history.length?`<div class="sectionhead"><h2>Recent results</h2></div><div class="panel">${history.slice(0,8).map(h=>`<div style="padding:12px 0;border-bottom:1px solid var(--line)"><a href="#node/${encodeURIComponent(h.id)}"><strong>${esc(h.title)}</strong> →</a><p class="small muted">${new Date(h.date).toLocaleDateString('en-IN')} · ${h.right}/${h.total} correct · ${Math.round(h.marks*100)/100} marks</p></div>`).join('')}</div>`:'');updateList();bindSearch()}
function typingSetup(n,raw){tool={type:'typing',node:n,passages:raw.passages||[],started:null,done:false};$('#app').innerHTML=head('Typing practice','Hindi + English passages',false)+`<div class="panel"><div class="formrow"><label>Passage<select class="field" id="passageSelect">${tool.passages.map((p,i)=>`<option value="${i}">${p.lang==='hi'?'Hindi':'English'} · Passage ${i+1}</option>`).join('')}</select></label><label>Duration<select class="field" id="typingduration"><option value="60">1 minute</option><option value="300">5 minutes</option><option value="600">10 minutes</option></select></label><span class="timer" id="typingtimer">01:00</span></div><div class="passage" id="passage"></div><button class="btn" id="starttyping">Start typing</button><textarea class="typing hide" id="typinginput" spellcheck="false" autocomplete="off" autocapitalize="off" aria-label="Type the passage here" placeholder="Type here..."></textarea><div class="metrics" id="typingstats"></div><div class="actions"><button class="btn secondary hide" id="finishtyping">Finish</button><button class="btn secondary hide" id="resettyping">Try again</button></div><p class="small muted">WPM = correct characters ÷ 5 ÷ minutes · Paste disabled</p></div>`;const setPassage=()=>{$('#passage').textContent=tool.passages[+$('#passageSelect').value]?.text||n.typingPassage||''};setPassage();$('#passageSelect').onchange=setPassage;$('#typingduration').onchange=()=>$('#typingtimer').textContent=timeText(+$('#typingduration').value);$('#typinginput').onpaste=e=>e.preventDefault();$('#starttyping').onclick=()=>{tool.started=Date.now();tool.duration=+$('#typingduration').value;$('#passageSelect').disabled=true;$('#typingduration').disabled=true;$('#starttyping').classList.add('hide');$('#typinginput').classList.remove('hide');$('#finishtyping').classList.remove('hide');$('#typinginput').focus();ticker=setInterval(()=>{if(tool?.type!=='typing'||tool.done)return;const left=Math.max(0,tool.duration-Math.floor((Date.now()-tool.started)/1000));$('#typingtimer').textContent=timeText(left);typingStats();if(!left)finishTyping()},500)};$('#typinginput').oninput=typingStats;$('#finishtyping').onclick=finishTyping;$('#resettyping').onclick=()=>typingSetup(n,raw)}
function typingStats(){if(!tool?.started)return;const text=$('#typinginput').value,passage=$('#passage').textContent;let right=0;for(let i=0;i<text.length;i++)if(text[i]===passage[i])right++;const elapsed=Math.min(tool.duration,(Date.now()-tool.started)/1000),wpm=elapsed?Math.round(right/5/(elapsed/60)):0;$('#typingstats').innerHTML=`<div class="metric"><b>${wpm}</b>WPM</div><div class="metric"><b>${text.length?Math.round(right/text.length*100):100}%</b>Accuracy</div><div class="metric"><b>${right}</b>Correct characters</div><div class="metric"><b>${text.length-right}</b>Errors</div>`}
function finishTyping(){typingStats();tool.done=true;clearInterval(ticker);$('#typinginput').disabled=true;$('#finishtyping').classList.add('hide');$('#resettyping').classList.remove('hide');toast('Typing practice complete')}
function calcSetup(n){tool={type:'calc',node:n,started:null,right:0,wrong:0,total:0};$('#app').innerHTML=head('Speed maths','60-second calculation practice',false)+`<div class="panel"><div class="formrow"><label>Mode<select class="field" id="calcmode"><option value="mix">Mixed</option><option value="multiply">Multiply</option><option value="square">Squares</option><option value="add">Addition</option></select></label><span class="timer" id="calctimer">01:00</span></div><div id="calcplay"><div class="calcq">Ready?</div><button class="btn" id="startcalc">Start practice →</button></div><div id="calcresult"></div></div>`;$('#startcalc').onclick=()=>{tool.started=Date.now();tool.mode=$('#calcmode').value;$('#calcmode').disabled=true;calcQuestion();ticker=setInterval(()=>{if(tool?.type!=='calc')return;const left=Math.max(0,60-Math.floor((Date.now()-tool.started)/1000));$('#calctimer').textContent=timeText(left);if(!left)finishCalc()},500)}}
function calcQuestion(){const r=(a,b)=>Math.floor(Math.random()*(b-a+1))+a;let mode=tool.mode==='mix'?['multiply','square','add'][r(0,2)]:tool.mode,a,b,label;if(mode==='square'){a=r(11,35);tool.answer=a*a;label=a+'²'}else if(mode==='multiply'){a=r(11,30);b=r(2,19);tool.answer=a*b;label=a+' × '+b}else{a=r(20,250);b=r(20,250);tool.answer=a+b;label=a+' + '+b}$('#calcplay').innerHTML=`<div class="calcq">${label}</div><form id="calcform" class="formrow" style="justify-content:center"><input class="field calcanswer" id="calcinput" type="number" inputmode="numeric" required aria-label="Your answer"><button class="btn">Check →</button></form><p class="small muted" style="text-align:center;margin-top:20px">${tool.right} correct · ${tool.wrong} wrong</p>`;$('#calcinput').focus();$('#calcform').onsubmit=e=>{e.preventDefault();if(Date.now()-tool.started>=60000){finishCalc();return}Number($('#calcinput').value)===tool.answer?tool.right++:tool.wrong++;tool.total++;calcQuestion()}}
function finishCalc(){clearInterval(ticker);const t=tool;$('#calcplay').innerHTML='<div class="calcq">Time up</div>';$('#calcresult').innerHTML=`<div class="metrics"><div class="metric"><b>${t.right}</b>Correct</div><div class="metric"><b>${t.wrong}</b>Wrong</div><div class="metric"><b>${t.total}</b>Attempted</div><div class="metric"><b>${t.total?Math.round(t.right/t.total*100):0}%</b>Accuracy</div></div><button class="btn" id="calcretry">Try again</button>`;$('#calcretry').onclick=()=>calcSetup(t.node)}
async function gateRedeem(code){try{const r=await gfetch('/api/gate?action=redeem',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code})});const d=await r.json();if(d.ok)localStorage.setItem('sb_gl','0');else localStorage.setItem('sb_gr',d.reason||'')}catch{}location.replace('#courses');renderRoute()}
function renderRoute(){const um=location.hash.match(/^#unlock=([A-Za-z0-9_-]{20,64})$/);if(um){$('#app').innerHTML='<div class="empty">Unlocking...</div>';gateRedeem(um[1]);return}if(!catalog)return;if(!(location.hash.slice(1)==='courses'||location.hash.slice(1).startsWith('course/')))gateClose();clearInterval(ticker);clearInterval(bannerTimer);tool=null;loadToken++;viewKey=location.hash.slice(1)||'home';query='';track('view',viewKey.startsWith('node/')?((byId.get(decodeURIComponent(viewKey.slice(5)))||{}).title||viewKey):viewKey);if(exam&&!exam.submitted){drawQuestion();return}exam=null;document.body.classList.remove('testing','reader-mode');$('#readerbar').innerHTML='';window.scrollTo(0,0);if(maintenanceActive())return maintenancePage();if(viewKey==='home')return home();if(viewKey==='donate')return donate();if(viewKey==='material')return material();if(viewKey==='library')return library();if(viewKey==='tools'){navRender('tools');crumb();$('#app').innerHTML=head('Tools','')+'<div class="grid" id="grid"></div>';updateList();bindSearch();return}if(maintenanceActive())return maintenancePage();if(viewKey==='managed-tests')return managedTests();if(viewKey.startsWith('managed-test/'))return managedTest(decodeURIComponent(viewKey.slice(13)));if(viewKey==='courses'||viewKey.startsWith('course/'))return courses(viewKey.startsWith('course/')?decodeURIComponent(viewKey.slice(7)):null);if(viewKey==='apps'){navRender('apps');crumb();$('#app').innerHTML=head('Apps','',false)+'<div class="empty">No apps yet.</div>';return}if(viewKey.startsWith('node/'))return openNode(decodeURIComponent(viewKey.slice(5)));const g=groupFor(viewKey);if(g)return collection(g,viewKey);location.hash='home'}
window.addEventListener('hashchange',()=>{if(exam&&!exam.submitted){const target=location.hash;confirmDialog('Leave test?','Your current answers will not be saved.',()=>{clearInterval(ticker);exam=null;document.body.classList.remove('testing');renderRoute()},'Leave test');$('#cancel').onclick=()=>{$('#dialog').close();window.history.replaceState(null,'','#node/'+encodeURIComponent(exam.node.id));};return}renderRoute()});window.addEventListener('beforeunload',e=>{if(exam&&!exam.submitted){e.preventDefault();e.returnValue=''}});
document.addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save){const id=save.dataset.save;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];const ok=store('sb_hub_saved_v2',saved);save.classList.toggle('selected',saved.includes(id));save.setAttribute('aria-pressed',String(saved.includes(id)));const item=byId.get(id)||groupById.get(id);save.setAttribute('aria-label',(saved.includes(id)?'Unsave ':'Save ')+(item?.title||''));save.textContent=saved.includes(id)?'▣':'▧';$('#savedcount').textContent=saved.length;if(viewKey==='library')updateList();toast(ok?(saved.includes(id)?'Saved to this browser':'Removed from library'):'Storage unavailable · Saved for this visit only')}const f=e.target.closest('[data-filter]');if(f){homeFilter=f.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x.dataset.filter===homeFilter);x.setAttribute('aria-pressed',x.dataset.filter===homeFilter)});updateList()}const reload=e.target.closest('[data-reload]');if(reload)openNode(reload.dataset.reload);const ext=e.target.closest('a[target="_blank"]');if(ext&&ext.href){try{track('link',new URL(ext.href).hostname)}catch{}}});
$('#privacy').onclick=()=>{$('#dialogbody').innerHTML=`<h2>Privacy</h2><p>Saved items and test results stay in this browser. Clearing site data removes them.</p><p>StudyBull keeps anonymous visit stats: pages opened and time spent, stored under a random visitor code. No name, phone number, email or screen recording is collected.</p><p>Your visitor code: <b>${esc(trkCode||'assigning...')}</b></p><p class="small muted">Study content loads from the original StudyBull portal. Hosting providers receive normal request data.</p><button class="btn" id="closeprivacy">Close</button>`;$('#dialog').showModal();$('#closeprivacy').onclick=()=>$('#dialog').close()};
(async()=>{try{const r=await fetch('sb-catalog.json');if(!r.ok)throw new Error('Catalog unavailable');catalog=await r.json();catalog.groups.forEach(g=>groupById.set(g.id,g));catalog.items.forEach(n=>{n.questions=n.questions||0;n.note=!!n.note;byId.set(n.id,n)});catalog.items.forEach(n=>{const chain=[];let p=byId.get(n.parent);while(p){chain.unshift(p.title);p=byId.get(p.parent)}n.path=[groupById.get(n.group).title,...chain]});saved=saved.filter(id=>byId.has(id)||groupById.has(id));renderRoute()}catch(e){$('#app').innerHTML='<div class="error">Unable to load. Please refresh.</div>'}})();

async function courses(id){navRender('courses');crumb();const token=loadToken;$('#app').innerHTML=head('Batches','',false)+'<div class="empty">Loading...</div>';if(localStorage.getItem('sb_gl')==='1'&&gjs('sb_gi')){gatePage(token,undefined,true);gateWarm()}try{const r=await gfetch('/api/courses');if(!r.ok)throw Error('Unable to load batches. Please retry.');const data=await r.json();if(token!==loadToken)return;if(data.gated){const gf=data.folders||[];$('#app').innerHTML=head('Batches','',false)+(gf.length?'<div class="grid">'+gf.map(f=>`<a class="card batchcard" href="#course/${encodeURIComponent(f.id)}"><span class="caps">▰ BATCH</span><h3>${esc(f.title)}</h3><p>${esc(f.description||'')}</p><span class="cardfoot">${f.linkCount||0} links · Locked 🔒</span></a>`).join('')+'</div>':'<div class="empty">No batches yet.</div>');localStorage.setItem('sb_gl','1');if(!document.getElementById('gateov'))await gatePage(token);else gateWarm();return}localStorage.setItem('sb_gl','0');gateClose();const folders=data.folders||[];if(id){const f=folders.find(f=>f.id===id);if(!f){$('#app').innerHTML=head('Folder not found','',false)+'<a class="textbtn" href="#courses">← All folders</a>';return}$('#app').innerHTML='<a class="textbtn" href="#courses">← All folders</a>'+head(f.title,f.description||'',false)+(f.links.length?'<div class="grid">'+f.links.map(l=>{let u;try{u=new URL(l.url)}catch{return ''}if(!['http:','https:'].includes(u.protocol))return '';return `<a class="card" href="${esc(u.href)}" target="_blank" rel="noopener noreferrer"><span class="caps">LINK ↗</span><h3>${esc(l.title)}</h3><p>${esc(u.hostname)}</p><span class="cardfoot">Open link →</span></a>`}).join('')+'</div>':'<div class="empty">No links yet.</div>');return}$('#app').innerHTML=head('Batches','',false)+(folders.length?'<div class="grid">'+folders.map(f=>`<a class="card batchcard" href="#course/${encodeURIComponent(f.id)}"><span class="caps">▰ BATCH</span><h3>${esc(f.title)}</h3><p>${esc(f.description||'')}</p><span class="cardfoot">${f.links.length} links · Open folder →</span></a>`).join('')+'</div>':'<div class="empty">No batches yet.</div>')}catch(e){if(token!==loadToken)return;$('#app').innerHTML=head('Batches','',false)+`<div class="empty">${esc(e.message)}<br><button class="textbtn" id="retrycourses">Retry</button></div>`;$('#retrycourses').onclick=()=>courses(id)}}

function validBanner(b){return b&&typeof b.image==='string'&&b.image.length<=260000&&/^data:image\/(jpeg|png|webp);base64,[a-zA-Z0-9+/=]+$/.test(b.image)}
function banner(){if(ownerContent.settings?.showBanners===false)return '';if(ownerContent.banners.length)return `<section class="banner custombanner" aria-label="StudyBull highlights" aria-roledescription="carousel"><div class="bannerslides">${ownerContent.banners.map((b,i)=>{let href='';try{const u=new URL(b.link);if(u.protocol==='https:')href=u.href}catch{}return `<${href?'a':'div'} ${href?`href="${esc(href)}" target="_blank" rel="noopener noreferrer"`:''} class="bannerslide ${i?'hide':''}" data-slide="${i}" aria-roledescription="slide" aria-label="${i+1} of ${ownerContent.banners.length}" ${i?'tabindex="-1"':''}><img src="${esc(b.image)}" alt="${esc(b.title||'StudyBull banner')}"></${href?'a':'div'}>`}).join('')}</div>${ownerContent.banners.length>1?`<div class="bannercontrols"><div class="bannerdots">${ownerContent.banners.map((b,i)=>`<button data-banner="${i}" aria-label="Show banner ${i+1}" aria-pressed="${!i}" class="${i?'':'selected'}"></button>`).join('')}</div><button id="bannerpause" aria-label="Pause banner rotation">Pause Ⅱ</button></div>`:''}</section>`;return `<section class="banner" aria-label="StudyBull highlights" aria-roledescription="carousel"><div class="bannerslides"><a href="#quiz" class="bannerslide" data-slide="0" aria-roledescription="slide" aria-label="1 of 2"><div><span class="caps">STUDYBULL HUB</span><h2>Study. Practice.<br>Keep going.</h2><span class="bannercta">Practice quizzes ↗</span></div><div class="bannerart" aria-hidden="true"><span>▤</span><span>◎</span><span>✦</span></div></a><a href="#courses" class="bannerslide second hide" data-slide="1" aria-roledescription="slide" aria-label="2 of 2" tabindex="-1"><div><span class="caps">LEARN AT YOUR PACE</span><h2>Your next topic.<br>All in one place.</h2><span class="bannercta">View batches ↗</span></div><div class="bannerart" aria-hidden="true"><span>▰</span><span>↗</span><span>✦</span></div></a></div><div class="bannercontrols"><div class="bannerdots"><button data-banner="0" aria-label="Show banner 1" aria-pressed="true" class="selected"></button><button data-banner="1" aria-label="Show banner 2" aria-pressed="false"></button></div><button id="bannerpause" aria-label="Pause banner rotation">Pause Ⅱ</button></div></section>`}
function startBanner(){clearInterval(bannerTimer);const box=$('.banner');if(!box||!$('#bannerpause'))return;const count=document.querySelectorAll('[data-slide]').length;let current=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,drag=null,skipClickUntil=0;const desktop=matchMedia('(hover: hover) and (pointer: fine)').matches;const show=i=>{current=(i+count)%count;document.querySelectorAll('[data-slide]').forEach((e,j)=>{e.classList.toggle('hide',j!==current);e.tabIndex=j===current?0:-1});document.querySelectorAll('[data-banner]').forEach((e,j)=>{e.classList.toggle('selected',j===current);e.setAttribute('aria-pressed',String(j===current))})};const sync=()=>{const b=$('#bannerpause');if(!b)return;b.textContent=paused?'Play ▷':'Pause Ⅱ';b.setAttribute('aria-label',paused?'Start banner rotation':'Pause banner rotation');clearInterval(bannerTimer);if(!paused)bannerTimer=setInterval(()=>{if(!document.hidden&&(!desktop||!box.matches(':hover,:focus-within')))show(current+1)},6000)};document.querySelectorAll('[data-banner]').forEach(e=>e.onclick=()=>{show(Number(e.dataset.banner));sync()});$('#bannerpause').onclick=()=>{paused=!paused;sync()};box.addEventListener('pointerdown',e=>{if(e.target.closest('.bannercontrols'))return;drag={x:e.clientX,y:e.clientY};if(e.pointerType==='mouse')e.preventDefault()});box.addEventListener('pointerup',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;drag=null;if(Math.abs(dx)>35&&Math.abs(dx)>Math.abs(dy)*1.2){show(current+(dx<0?1:-1));skipClickUntil=Date.now()+500;sync()}});box.addEventListener('pointercancel',()=>{drag=null});box.addEventListener('click',e=>{if(Date.now()<skipClickUntil){e.preventDefault();e.stopPropagation()}},true);sync()}

function donate(){navRender('donate');crumb();$('#app').innerHTML=head('Donate','',false)+`<section class="donatepanel"><span class="donateicon" aria-hidden="true">♡</span><h2>Help keep StudyBull free.</h2><p>StudyBull is 100% free, without large ads or paid access.</p><p>Optional donations will help pay for new servers and domains.</p>${ownerContent.donationMessage?`<p class="donatemessage">${esc(ownerContent.donationMessage)}</p>`:''}<div class="donatestatus">Donations are not open yet.</div><a class="textbtn" href="#material">Keep learning →</a></section>`}


function maintenanceActive(){return ownerContent.settings?.emergencyLock||ownerContent.settings?.maintenanceMode}
function maintenancePage(){navRender('home');crumb();const emergency=ownerContent.settings?.emergencyLock,msg=emergency?ownerContent.settings?.emergencyMessage:ownerContent.settings?.maintenanceMessage;$('#app').innerHTML=`<section class="lockscreen"><span class="donateicon" aria-hidden="true">${emergency?'!':'↺'}</span><h1>${emergency?'StudyBull is temporarily locked':'StudyBull is under maintenance'}</h1><p class="muted">${esc(msg||(emergency?'Please check back shortly.':'We are updating the site. Please check back shortly.'))}</p></section>`}
function notices(){const update=ownerContent.appUpdate||{};return `${(ownerContent.notifications||[]).map(n=>`<div class="topnotice"><b>${esc(n.title)}</b><span>${esc(n.message)}</span></div>`).join('')}${update.active?`<div class="topnotice update"><b>App update ${esc(update.version||'')}</b><span>${esc(update.message||'A new update is available.')}</span>${update.link?`<a href="${esc(update.link)}" target="_blank" rel="noopener noreferrer">Open ↗</a>`:''}</div>`:''}`}
function managedHome(){const tests=ownerContent.mocks||[],classes=(ownerContent.liveClasses||[]).filter(c=>c.status!=='ended').slice(0,4);return `${tests.length?`<section class="managedsection"><div class="sectionhead"><h2>Custom mock tests</h2><a class="textbtn" href="#managed-tests">View all →</a></div><div class="grid">${tests.slice(0,3).map(testCard).join('')}</div></section>`:''}${classes.length?`<section class="managedsection"><div class="sectionhead"><h2>Live classes</h2></div><div class="grid">${classes.map(classCard).join('')}</div></section>`:''}`}
function testCard(m){return `<a class="card batchcard" href="#managed-test/${encodeURIComponent(m.id)}"><span class="caps">CUSTOM TEST</span><h3>${esc(m.title)}</h3><p>${esc(m.description||m.subject||'')}</p><span class="cardfoot">${m.questionCount} questions · ${m.durationMinutes} min →</span></a>`}
function classCard(c){const live=c.status==='live';return `<a class="card batchcard" href="${esc(c.link)}" target="_blank" rel="noopener noreferrer"><span class="caps">${live?'LIVE NOW':'CLASS'}</span><h3>${esc(c.title)}</h3><p>${esc(c.subject||'')} · ${new Date(c.startsAt).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'})}</p><span class="cardfoot">${live?'Join live':'Open class'} ↗</span></a>`}
function managedMaterial(){const notes=ownerContent.notes||[],pyqs=ownerContent.pyqs||[];const linkCard=(x,type)=>`<a class="card" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer"><div class="cover ${type==='pdf'?'orange':'blue'}"><i>${type==='pdf'?'▤':'▧'}</i><small>${type==='pdf'?'PDF':'NOTE'}</small></div><div class="body"><span class="tag">${esc(x.subject||x.category||x.exam||'StudyBull')}</span><h3>${esc(x.title)}</h3><p>${esc(x.description||[x.exam,x.year,x.subject,x.chapter].filter(Boolean).join(' · '))}</p><span class="cardfoot">Open ↗</span></div></a>`;return `${notes.length?`<section class="managedsection"><div class="sectionhead"><h2>Owner notes & PDFs</h2></div><div class="grid">${notes.map(n=>linkCard(n,n.type)).join('')}</div></section>`:''}${pyqs.length?`<section class="managedsection"><div class="sectionhead"><h2>Owner PYQ collection</h2></div><div class="grid">${pyqs.map(p=>linkCard(p,'pyq')).join('')}</div></section>`:''}`}
function managedTests(){navRender('material');crumb();$('#app').innerHTML=head('Custom mock tests','Created by the StudyBull owner',false)+(ownerContent.mocks?.length?`<div class="grid">${ownerContent.mocks.map(testCard).join('')}</div>`:'<div class="empty">No custom tests yet.</div>')}
async function managedTest(id){navRender('material');crumb();$('#app').innerHTML=head('Custom mock test','',false)+'<div class="empty">Loading...</div>';try{const r=await fetch(SB_API+'/api/courses?action=test&id='+encodeURIComponent(id),{cache:'no-store'});if(!r.ok)throw Error('Test unavailable.');const t=await r.json();$('#app').innerHTML=head(t.title,t.description||'',false)+`<section class="panel"><p>${t.questions.length} questions · ${t.durationMinutes} minutes</p><button class="btn" id="startmanaged">Start test</button></section>`;$('#startmanaged').onclick=()=>{track('test-start',t.title);drawManaged(t)}}catch(e){$('#app').innerHTML=head('Custom mock test','',false)+`<div class="empty">${esc(e.message)}</div>`}}
function drawManaged(t){const answers=Array(t.questions.length).fill(null);$('#app').innerHTML=head(t.title,'Choose one answer for each question.',false)+`<form id="managedform">${t.questions.map((q,i)=>`<section class="questioncard"><h3>${i+1}. ${esc(q.question)}</h3>${q.options.map((o,j)=>`<label class="optionrow"><input type="radio" name="q${i}" value="${j}"> <span>${esc(o)}</span></label>`).join('')}</section>`).join('')}<button class="btn">Submit test</button></form><div id="managedresult"></div>`;$('#managedform').onsubmit=async e=>{e.preventDefault();t.questions.forEach((q,i)=>{const x=document.querySelector(`input[name="q${i}"]:checked`);answers[i]=x?Number(x.value):null});const btn=e.target.querySelector('button');btn.disabled=true;try{const r=await fetch(SB_API+'/api/courses?action=submit-test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:t.id,answers})});const d=await r.json();if(!r.ok)throw Error(d.error||'Could not submit test.');track('test-done',d.score+'/'+d.total+' correct · '+t.title);$('#managedresult').innerHTML=`<section class="panel resultpanel"><h2>Score: ${d.score}/${d.total}</h2>${d.review.map((r,i)=>`<div class="reviewline ${r.correct?'right':'wrong'}"><b>${i+1}. ${r.correct?'Correct':'Wrong'}</b><p>Correct option: ${esc(t.questions[i].options[r.answer])}</p>${r.explanation?`<p>${esc(r.explanation)}</p>`:''}</div>`).join('')}</section>`;$('#managedresult').scrollIntoView({behavior:'smooth'})}catch(err){alert(err.message);btn.disabled=false}}}
function showManagedPopup(){const p=(ownerContent.popups||[])[0];if(!p||$('#dialog').open)return;let seen=readStore('sb_hub_popup_seen_v1',[]);if(!Array.isArray(seen))seen=[];if(seen.includes(p.id))return;$('#dialogbody').innerHTML=`<h2>${esc(p.title)}</h2><p style="white-space:pre-wrap">${esc(p.message)}</p><div class="actions">${p.link?`<a class="btn" href="${esc(p.link)}" target="_blank" rel="noopener noreferrer">Open</a>`:''}<button class="btn secondary" id="closepopup">Close</button></div>`;$('#dialog').showModal();$('#closepopup').onclick=()=>{$('#dialog').close();store('sb_hub_popup_seen_v1',[...seen,p.id].slice(-30))}}

let ownerRevision=null,ownerPending=null,ownerNext=0,ownerGated=false;
const devId=(()=>{try{let d=localStorage.getItem('sb_dev');if(!/^[A-Za-z0-9_-]{20,64}$/.test(d||'')){const a=new Uint8Array(24);crypto.getRandomValues(a);d=btoa(String.fromCharCode(...a)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=/g,'');localStorage.setItem('sb_dev',d)}return d}catch{return 'x'.repeat(24)}})();
const gfetch=(u,o={})=>fetch(SB_API+u,{cache:'no-store',...o,headers:{...(o.headers||{}),Authorization:'Bearer '+devId}});
let gatePoll=null;
function gateClose(){clearInterval(gatePoll);const o=document.getElementById('gateov');if(o)o.remove();document.body.style.overflow=''}
const gjs=k=>{try{return JSON.parse(localStorage.getItem(k)||'null')}catch{return null}};
async function gateWarm(){try{const i=await(await gfetch('/api/gate?action=info')).json();if(i&&i.enabled)localStorage.setItem('sb_gi',JSON.stringify({name:i.name,link:i.link}));const st=await(await gfetch('/api/gate?action=status')).json();localStorage.setItem('sb_gr',st.reason||'')}catch{}}
async function gatePage(token,reason,instant){clearInterval(gatePoll);gateClose();let info=gjs('sb_gi')||{};if(!info.name){try{info=await(await gfetch('/api/gate?action=info')).json();localStorage.setItem('sb_gi',JSON.stringify({name:info.name,link:info.link}))}catch{}}else if(!instant)gateWarm();if(!reason)reason=localStorage.getItem('sb_gr')||'';if(!reason&&!instant){try{reason=(await(await gfetch('/api/gate?action=status')).json()).reason}catch{}}
if(token!==undefined&&token!==loadToken)return;
const msg=reason==='left'?'You left our channel, so access is locked. Join again to unlock.':'Batches and course videos are for members of our Telegram channel.';
const o=document.createElement('div');o.id='gateov';o.setAttribute('role','dialog');o.setAttribute('aria-modal','true');o.setAttribute('aria-labelledby','gatetitle');o.style.cssText='position:fixed;inset:0;z-index:99;background:#0b1220;display:flex;align-items:center;justify-content:center;padding:22px;overflow:auto;font-family:inherit';
const nm=esc(info.name||'StudyBull');
o.innerHTML=`<div style="background:#1e293b;border:1px solid #2a3850;border-radius:26px;max-width:400px;width:100%;padding:28px 22px;text-align:center;box-shadow:0 18px 50px rgba(0,0,0,.45);color:#fff"><div style="width:62px;height:62px;border-radius:18px;background:linear-gradient(135deg,#ffc400,#ff9500);margin:0 auto 20px;display:flex;align-items:center;justify-content:center" aria-hidden="true"><svg width="32" height="32" viewBox="0 0 24 24"><path fill="#fff" d="M12 2 4 5v6c0 5 3.4 9.7 8 11 4.6-1.3 8-6 8-11V5l-8-3Zm0 2.2 6 2.3V11c0 4-2.6 7.7-6 8.9V4.2Z"/></svg></div><h2 id="gatetitle" style="margin:0 0 8px;font-size:22px;color:#fff">Join Required Channels</h2><p style="margin:0 0 20px;color:#94a3b8;line-height:1.5">${esc(msg)}</p><div style="display:flex;align-items:center;gap:12px;background:#1b2638;border:1px solid #2a3850;border-radius:16px;padding:12px"><span style="width:38px;height:38px;border-radius:50%;background:#16406b;display:flex;align-items:center;justify-content:center;flex:none" aria-hidden="true"><svg width="22" height="22" viewBox="0 0 24 24"><path fill="#3b9cff" d="M18 11v2h4v-2h-4zm-2 6.61c.96.71 2.21 1.65 3.2 2.39.4-.53.8-1.07 1.2-1.6-.99-.74-2.24-1.68-3.2-2.4-.4.54-.8 1.08-1.2 1.61zM20.4 5.6c-.4-.53-.8-1.07-1.2-1.6-.99.74-2.24 1.68-3.2 2.4.4.53.8 1.07 1.2 1.6.96-.72 2.21-1.65 3.2-2.4zM4 9c-1.1 0-2 .9-2 2v2c0 1.1.9 2 2 2h1v4h2v-4h1l5 3V6L8 9H4zm11.5 3c0-1.33-.58-2.53-1.5-3.35v6.69c.92-.81 1.5-2.01 1.5-3.34z"/></svg></span><b style="flex:1;text-align:left;color:#fff">${nm}</b><a id="gatejoin" ${info.link?`href="${esc(info.link)}" target="_blank" rel="noopener"`:'href="#"'} style="flex:none;border:1px solid #b9475a;background:#5a3043;color:#ff6b7d;border-radius:10px;padding:9px 16px;text-decoration:none;font-weight:600">↗ Join</a></div><button id="gateverify" style="margin-top:22px;width:100%;border:0;border-radius:16px;background:#00c27a;color:#fff;font-size:17px;font-weight:700;padding:16px;cursor:pointer">I've Joined, Verify</button><p id="gatestate" role="status" style="min-height:18px;margin:14px 0 0;color:#94a3b8;font-size:13px">Tap verify once you have joined, then press Start in the bot.</p><a href="#home" id="gatenot" style="display:inline-block;margin-top:8px;font-size:13px;color:#94a3b8">Not now, go to Home</a></div>`;
document.body.appendChild(o);document.body.style.overflow='hidden';
$('#gatenot').onclick=()=>{gateClose()};
$('#gateverify').onclick=async()=>{const st=$('#gatestate');st.textContent='Opening Telegram...';try{const r=await gfetch('/api/gate?action=start',{method:'POST'});const d=await r.json();if(!r.ok||!d.url)throw Error();window.open(d.url,'_blank','noopener');st.textContent='Press Start in Telegram, then come back. Checking...';let n=0;clearInterval(gatePoll);gatePoll=setInterval(async()=>{n++;try{const s2=await(await gfetch('/api/gate?action=status')).json();if(s2.ok){clearInterval(gatePoll);localStorage.setItem('sb_gl','0');gateClose();ownerRevision=null;refreshOwner(true);renderRoute()}}catch{}if(n>60){clearInterval(gatePoll);st.textContent='Not verified yet. Join the channel, then tap Verify again.'}},3000)}catch{st.textContent='Could not start verification. Try again.'}}}
function announcement(){const t=ownerContent.settings?.announcement;return t?`<p class="empty" style="padding:14px;text-align:left;white-space:pre-wrap">${esc(t)}</p>`:''}
function ownerViewState(){const s=ownerContent.settings||{},lock=JSON.stringify([s.maintenanceMode===true,s.emergencyLock===true,s.maintenanceMessage||'',s.emergencyMessage||'']);if(viewKey==='home')return lock+JSON.stringify([ownerContent.banners,s.homeTitle||'',s.batchesLabel||'',s.materialLabel||'',s.announcement||'',s.showBanners!==false,ownerContent.mocks,ownerContent.liveClasses,ownerContent.notifications,ownerContent.appUpdate,ownerContent.popups]);if(viewKey==='donate')return lock+ownerContent.donationMessage;if(viewKey==='material')return lock+JSON.stringify([s.materialIntro||'',ownerContent.notes,ownerContent.pyqs]);if(viewKey==='managed-tests'||viewKey.startsWith('managed-test/'))return lock+JSON.stringify(ownerContent.mocks||[]);if(viewKey==='courses'||viewKey.startsWith('course/'))return lock+JSON.stringify(ownerContent.folders||[]);return lock}
async function refreshOwner(force=false){if(ownerPending)return ownerPending;if(!force&&Date.now()<ownerNext)return;ownerNext=Date.now()+12000;ownerPending=(async()=>{try{const r=await gfetch('/api/courses'+(ownerRevision?'?'+new URLSearchParams({known:ownerRevision,g:ownerGated?'0':'1'}):''));if(!r.ok)throw Error('Content refresh unavailable');const d=await r.json();if(d.unchanged||ownerRevision===d.revision&&ownerGated===Boolean(d.gated))return;ownerGated=Boolean(d.gated);const initial=ownerRevision===null,before=ownerViewState();ownerRevision=d.revision;ownerContent={folders:Array.isArray(d.folders)?d.folders:[],banners:(Array.isArray(d.banners)?d.banners:[]).filter(validBanner).slice(0,4),donationMessage:typeof d.donationMessage==='string'?d.donationMessage.slice(0,600):'',settings:d.settings||{},notes:Array.isArray(d.notes)?d.notes:[],pyqs:Array.isArray(d.pyqs)?d.pyqs:[],mocks:Array.isArray(d.mocks)?d.mocks:[],liveClasses:Array.isArray(d.liveClasses)?d.liveClasses:[],notifications:Array.isArray(d.notifications)?d.notifications:[],popups:Array.isArray(d.popups)?d.popups:[],appUpdate:d.appUpdate||{}};showManagedPopup();if(!catalog||exam&&!exam.submitted||before===ownerViewState())return;const y=scrollY;if(viewKey==='home')home();else if(viewKey==='donate')donate();else if(viewKey==='material'){const q=query;material();query=q;if($('#search'))$('#search').value=q;updateList()}else if(viewKey==='courses'||viewKey.startsWith('course/'))await courses(viewKey.startsWith('course/')?decodeURIComponent(viewKey.slice(7)):null);else if(viewKey==='managed-tests')managedTests();else if(viewKey.startsWith('managed-test/'))await managedTest(decodeURIComponent(viewKey.slice(13)));else if(maintenanceActive())maintenancePage();if(!initial)window.scrollTo(0,y)}catch(e){console.warn('Published content refresh will retry.')}finally{ownerPending=null}})();return ownerPending}
refreshOwner(true);setInterval(()=>{if(!document.hidden&&navigator.onLine)refreshOwner()},15000);window.addEventListener('focus',()=>refreshOwner());window.addEventListener('online',()=>refreshOwner(true));document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshOwner()});


async function loadNode(n){if(rawById.has(n.id))return rawById.get(n.id);if(nodeLoads.has(n.id))return nodeLoads.get(n.id);const g=groupById.get(n.group||n.id),url='https://studybull-hub.vercel.app/api/content?'+new URLSearchParams({group:g.id,id:n.id,v:g.version});const p=(async()=>{try{let r;try{r=await(await caches.open('studybull-nodes-v1')).match(url)}catch{}if(!r){r=await fetch(url);if(!r.ok)throw Error('Node unavailable');const copy=r.clone();const d=await r.json();if(d.snapshot!==g.sha256||String(d.item?.id)!==n.id)throw Error('Snapshot mismatch');rawById.set(n.id,d.item);try{await(await caches.open('studybull-nodes-v1')).put(url,copy)}catch{}return d.item}const d=await r.json();if(d.snapshot!==g.sha256||String(d.item?.id)!==n.id)throw Error('Snapshot mismatch');rawById.set(n.id,d.item);return d.item}catch{await loadGroup(g.id);return rawById.get(n.id)}})();nodeLoads.set(n.id,p);try{return await p}finally{nodeLoads.delete(n.id)}}
function prefetch(n){if(navigator.connection?.saveData||/2g/.test(navigator.connection?.effectiveType||''))return;const items=(n.children||[]).map(id=>byId.get(id)).filter(n=>n&&!n.children.length).slice(0,2);const run=()=>items.forEach(n=>loadNode(n).catch(()=>{}));if('requestIdleCallback'in window)requestIdleCallback(run,{timeout:1500});else setTimeout(run,400)}

const TRK_API=SB_API+'/api/courses';
let trkVid=readStore('sb_hub_vid',''),trkCode=readStore('sb_hub_vcode',''),trkQueue=[],trkSec=0,trkReady=false,trkLastBeat=Date.now();
function trkDevice(){const ua=navigator.userAgent||'';if(/iPad|Tablet/i.test(ua))return 'z';if(/Mobi|Android|iPhone/i.test(ua)||innerWidth<760)return 'x';return 'y'}
function trkSource(){try{const p=new URLSearchParams(location.search);const ref=(p.get('ref')||'').slice(0,40);if(ref)return ['sh',ref];const s=(p.get('s')||'').toLowerCase();if(['tg','wa','gg','wb'].includes(s))return [s,''];const h=document.referrer?new URL(document.referrer).hostname:'';if(/(^|\.)t\.me$|telegram/i.test(h))return ['tg',''];if(/whatsapp/i.test(h))return ['wa',''];if(/google\./i.test(h))return ['gg','']}catch{}return ['wb','']}
function track(type,detail=''){try{trkQueue.push({at:new Date().toISOString(),type,detail:String(detail).slice(0,140)});if(trkQueue.length>50)trkQueue.shift();store('sb_hub_vseen',Date.now());if(trkQueue.length>=15)trkFlush()}catch{}}
function trkBeat(){const now=Date.now();if(document.visibilityState==='visible')trkSec+=Math.max(0,Math.min(120,Math.round((now-trkLastBeat)/1000)));trkLastBeat=now}
async function trkRegister(){if(trkCode&&trkVid){trkReady=true;return}if(!trkVid&&crypto.randomUUID)trkVid=crypto.randomUUID();if(!trkVid)return;const [src,ref]=trkSource();try{const r=await fetch(TRK_API+'?action=track',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({vid:trkVid,register:true,source:src,device:trkDevice(),ref})});const d=await r.json();if(d&&d.code){trkCode=d.code;trkReady=true;store('sb_hub_vid',trkVid);store('sb_hub_vcode',trkCode)}}catch{}}
function trkFlush(){if(!trkReady||!trkVid||!trkQueue.length&&!trkSec)return;const events=trkQueue,sec=trkSec,body=JSON.stringify({vid:trkVid,events,sec});trkQueue=[];trkSec=0;let sent=false;try{sent=navigator.sendBeacon&&navigator.sendBeacon(TRK_API+'?action=track',new Blob([body],{type:'text/plain'}))}catch{}if(sent)return;fetch(TRK_API+'?action=track',{method:'POST',headers:{'Content-Type':'application/json'},body,keepalive:true}).then(r=>r.json()).then(d=>{if(d&&d.known===false){trkReady=false;trkCode='';store('sb_hub_vcode','');trkRegister().then(trkFlush)}}).catch(()=>{trkQueue.unshift(...events);trkSec+=sec;if(trkQueue.length>50)trkQueue.length=50})}
(function trkBoot(){try{const last=Number(readStore('sb_hub_vseen',0))||0;if(trkCode&&Date.now()-last>1800000)track('visit','');trkRegister().then(()=>trkFlush());setInterval(()=>{trkBeat();if(trkSec>=60||trkQueue.length>=10)trkFlush()},30000);document.addEventListener('visibilitychange',()=>{trkBeat();if(document.visibilityState==='hidden')trkFlush()});window.addEventListener('pagehide',()=>{trkBeat();trkFlush()})}catch{}})();
